CREATE SCHEMA IF NOT EXISTS pitlane;
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='pitlane_web') THEN CREATE ROLE pitlane_web NOLOGIN NOBYPASSRLS; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='pitlane_worker') THEN CREATE ROLE pitlane_worker NOLOGIN NOBYPASSRLS; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='pitlane_billing') THEN CREATE ROLE pitlane_billing NOLOGIN NOBYPASSRLS; END IF; END $$;
REVOKE ALL ON SCHEMA pitlane FROM PUBLIC;
GRANT USAGE ON SCHEMA pitlane TO pitlane_web,pitlane_worker,pitlane_billing;
CREATE TABLE IF NOT EXISTS pitlane.runtime(id boolean PRIMARY KEY DEFAULT true CHECK(id),mode text NOT NULL CHECK(mode IN('local','staging','production')));
CREATE TABLE IF NOT EXISTS pitlane.tenants(id uuid PRIMARY KEY,name text NOT NULL,deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS pitlane.tenant_memberships(tenant_id uuid REFERENCES pitlane.tenants,user_id uuid,role text NOT NULL CHECK(role IN('owner','admin','billing','member')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS pitlane.projects(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES pitlane.tenants,name text NOT NULL,deleted_at timestamptz,UNIQUE(id,tenant_id));
CREATE TABLE IF NOT EXISTS pitlane.project_memberships(tenant_id uuid,project_id uuid,user_id uuid,role text NOT NULL CHECK(role IN('admin','developer','viewer')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,project_id,user_id),FOREIGN KEY(project_id,tenant_id) REFERENCES pitlane.projects(id,tenant_id),FOREIGN KEY(tenant_id,user_id) REFERENCES pitlane.tenant_memberships(tenant_id,user_id));
CREATE OR REPLACE FUNCTION pitlane.actor_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('pitlane.actor_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION pitlane.actor_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('pitlane.tenant_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION pitlane.can_tenant(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT t=pitlane.actor_tenant() AND EXISTS(SELECT FROM pitlane.tenant_memberships m JOIN pitlane.tenants x ON x.id=m.tenant_id WHERE m.tenant_id=t AND m.user_id=pitlane.actor_id() AND m.active AND x.deleted_at IS NULL) $$;
CREATE OR REPLACE FUNCTION pitlane.can_project(t uuid,p uuid,writing boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT pitlane.can_tenant(t) AND EXISTS(SELECT FROM pitlane.projects pr JOIN pitlane.tenant_memberships m ON m.tenant_id=pr.tenant_id AND m.user_id=pitlane.actor_id() WHERE pr.id=p AND pr.tenant_id=t AND pr.deleted_at IS NULL AND (m.role IN('owner','admin') OR EXISTS(SELECT FROM pitlane.project_memberships pm WHERE pm.tenant_id=t AND pm.project_id=p AND pm.user_id=m.user_id AND pm.active AND (NOT writing OR pm.role IN('admin','developer'))))) $$;
CREATE OR REPLACE FUNCTION pitlane.can_billing(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT pitlane.can_tenant(t) AND EXISTS(SELECT FROM pitlane.tenant_memberships WHERE tenant_id=t AND user_id=pitlane.actor_id() AND role IN('owner','admin','billing') AND active) $$;
ALTER TABLE pitlane.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE pitlane.tenant_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE pitlane.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE pitlane.project_memberships ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_read ON pitlane.tenants;
CREATE POLICY tenant_read ON pitlane.tenants FOR SELECT USING(pitlane.can_tenant(id));
DROP POLICY IF EXISTS membership_read ON pitlane.tenant_memberships;
CREATE POLICY membership_read ON pitlane.tenant_memberships FOR SELECT USING(pitlane.can_tenant(tenant_id));
DROP POLICY IF EXISTS project_read ON pitlane.projects;
CREATE POLICY project_read ON pitlane.projects FOR SELECT USING(pitlane.can_project(tenant_id,id));
DROP POLICY IF EXISTS member_read ON pitlane.project_memberships;
CREATE POLICY member_read ON pitlane.project_memberships FOR SELECT USING(pitlane.can_project(tenant_id,project_id));
GRANT SELECT ON pitlane.tenants,pitlane.tenant_memberships,pitlane.projects,pitlane.project_memberships TO pitlane_web;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.actor_id(),pitlane.actor_tenant(),pitlane.can_tenant(uuid),pitlane.can_project(uuid,uuid,boolean),pitlane.can_billing(uuid) TO pitlane_web;
